import{_ as r,l,o as e,c as n,v as i,p as s,x as t,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"设计规则的起源","description":"","frontmatter":{"title":"设计规则的起源","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/design-rule-origin.md","filePath":"litho/design-rule-origin.md","lastUpdated":1789023840000}'),E={name:"litho/design-rule-origin.md"};function c(A,a,m,_,u,f){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="设计规则的起源" tabindex="-1">设计规则的起源 <a class="header-anchor" href="#设计规则的起源" aria-label="Permalink to &quot;设计规则的起源&quot;">​</a></h1><div class="epigraph"><p>设计规则不是从瑞利公式抄下来的整数；它们是成像、套刻、刻蚀、电学与良率谈出来的可交货集合，写进手册之后才看起来像几何。</p><footer>—— 对照 Levinson 对设计规则与工艺能力的讨论；DTCO 把规则当作协同输出</footer></div><p><a href="/litho/decomposition-coloring-conflict">上一课</a>把不可染色写成硬失败。缺口是回溯：手册里最小间隔、最小宽度、via 覆盖、密度窗，最初是哪一截物理不够用。<a href="/litho/dtco-patterning">DTCO</a> 已说规则是协同输出；本课钉起源清单，供后课把面积、轨道、SRAM 读成规则的后果。最小面积与 tip-to-tip 的专项，留给[下一课](/litho/min-area-tip-to-tip）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>瑞利 \\(CD = k_1\\lambda/\\mathrm{NA}\\) 只给节距量级。真实规则还包括：掩模可写（MRC）、胶塌缩与随机桥断、刻蚀 ARDE、CMP 密度、对准标记禁区、电学漏电与可靠性间距。每一条「min space = x nm」都是某一失效模式的代理，而不是光学分辨率的别名。</p><p>缺口是<strong>把规则读成失效模式</strong>，不是从第一性原理重讲成像。<a href="/litho/overlay-budget">套刻预算</a> 已经分解位置误差；via 覆盖规则有一截就是这笔预算的几何化。把规则当神圣整数，LFD 无法谈判；把规则当随便可破，LRC 失门。</p><h3 id="规则是冻结的窗口" tabindex="-1">规则是冻结的窗口 <a class="header-anchor" href="#规则是冻结的窗口" aria-label="Permalink to &quot;规则是冻结的窗口&quot;">​</a></h3><p>工艺窗随胶、光源、腔体漂。规则版本必须与 OPC 模型、刻蚀核、分解选项同发。节点中期换 EUV 单次，旧双重规则应整段退休，而不是叠床架屋。起源课的用处是：改一条规则时知道要重开哪一扇窗。</p><p><span class="marginnote">同一数字可能同时服务光学与可靠性。收紧「只为了好印」可能在电学上无意义，或反过来。改规则要声明主失效。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把手册条款映射到来源：光学/PV-band、分解/着色、套刻/覆盖、刻蚀/密度、CMP、可靠性、可制造性（填充、狭缝均匀）。每条附：计量如何验证、LRC 如何检查、例外是否存在（SRAM 常有自己的规则族）。与 <a href="/litho/litho-process-flow">光刻流程</a> 的关系：规则是流程能力的接口，不是流程本身。</p><p>起源清楚后，LFD 才知道该改库还是该改工艺。</p><p>手册修订走变更控制：改一条 min space，要列出受影响的 OPC 核、分解选项、PWQ 矩阵和电学可靠性条款。Levinson 把设计规则写成工艺能力的接口；本课要求接口变更有追溯，而不是在邮件里改一个整数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光学给出可印节距与二维禁区；套刻把「不同层之间」变成覆盖与 tip 规则；刻蚀把密度变成填充规则；随机把稀疏孔的面积规则收得比均值 CD 更严。设计规则检查是这些物理在多边形上的投影。投影有信息损失：合法图形仍可能是热点，故需要 LRC；热点合法化又可能倒逼加规则。</p>',15)),(e(),s(h,null,{default:t(()=>[d(o,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHYS%5B%22%E5%85%89%E5%AD%A6%20%E5%A5%97%E5%88%BB%20%E5%88%BB%E8%9A%80%20%E9%9A%8F%E6%9C%BA%22%5D%20--%3E%20DR%5B%22%E8%AE%BE%E8%AE%A1%E8%A7%84%E5%88%99%E6%9D%A1%E6%AC%BE%22%5D%0A%20%20DR%20--%3E%20DRC%5B%22DRC%20%E5%87%A0%E4%BD%95%E9%97%A8%22%5D%0A%20%20DR%20--%3E%20LRC%5B%22LRC%20%E6%A8%A1%E5%9E%8B%E9%97%A8%22%5D%0A%20%20FAIL%5B%22%E7%A1%85%E4%B8%8A%E5%A4%B1%E6%95%88%22%5D%20--%3E%20NEW%5B%22%E6%96%B0%E6%9D%A1%E6%AC%BE%E6%88%96%E6%94%B6%E7%B4%A7%22%5D%0A%20%20NEW%20--%3E%20DR%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写限价簿或 Transformer。不把某代工厂未公开的规则数值表当作文献。规则起源随节点变，历史数字不可当现节点规格。</p><p>后课默认：读规则先问失效模式。下一课专攻面积与 tip-to-tip——二维图形化最常被光学和套刻同时咬的两条。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>设计规则是多物理失效模式的几何代理，不是瑞利公式的整数翻版。</li><li>版本与模型、分解、腔体同发。</li><li>合法不等于可印；LRC 补投影损失。</li><li>出处：Levinson《Principles of Lithography》；DTCO 与设计规则公开论述。</li></ul>',5))])}const B=r(E,[["render",c]]);export{C as __pageData,B as default};
